### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b, c, m;   // 现在时刻、公交耗时、出租耗时、进站检票耗时
    int p, q, t;      // 公交票价、出租票价、火车发车时刻
    cin >> a >> b >> c >> m;
    cin >> p >> q >> t;

    // 到站台的时刻 = 出发时刻 + 路上时间 + 进站检票时间
    int by_bus = a + b + m;
    int by_taxi = a + c + m;

